package org.eclipse.rdf4j.sail.lmdb;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

/** Prepares the JVM temporary directories before Surefire starts its test forks. */
public final class LmdbTestForkDirectories {

	private LmdbTestForkDirectories() {
	}

	public static void main(String[] args) throws IOException {
		int projects = Integer.parseInt(System.getProperty("rdf4j.lmdb.test.reactorConcurrency"));
		Path root = resolveTemporaryRoot(Path.of(args[2]), Path.of(args[0]));
		prepare(root, args[1], Runtime.getRuntime().availableProcessors(), projects);
	}

	static Path resolveTemporaryRoot(Path projectDirectory, Path temporaryRoot) {
		return projectDirectory.resolve(temporaryRoot).toAbsolutePath().normalize();
	}

	static void prepare(Path root, String forkCount, int processors, int concurrentProjects) throws IOException {
		int count = effectiveForkCount(forkCount, processors);
		if (count < 0 || concurrentProjects < 1) {
			throw new IllegalArgumentException("Invalid test fork or reactor concurrency");
		}
		int slots = Math.multiplyExact(count, concurrentProjects);
		for (int fork = 1; fork <= slots; fork++) {
			Files.createDirectories(root.resolve("fork-" + fork));
		}
	}

	static int effectiveForkCount(String forkCount, int processors) {
		String value = forkCount.trim();
		if (value.endsWith("C")) {
			double count = Double.parseDouble(value.substring(0, value.length() - 1)) * processors;
			return count > 0 ? Math.max(1, (int) count) : 0;
		}
		return Integer.parseInt(value);
	}
}
